const templateCache = [];
function renderRow(data) {
  const tr = document.createElement("tr");
  tr.innerHTML = `<td>${data.name}</td>`;
  tbody.appendChild(tr);
  templateCache.push(tr); // leak: removed rows stay in cache
  return tr;
}

function renderRow(data, cache) {
  const tr = document.createElement("tr");
  tr.textContent = data.name;
  if (cache.size > 100) cache.delete(cache.keys().next().value);
  cache.set(data.id, tr);
  return tr;
}

let chartContainer = null;
function mountChart(el) {
  chartContainer = el;
  d3.select(el).selectAll("*").data(data).enter().append("div");
}
function unmountChart() {
  if (chartContainer) {
    d3.select(chartContainer).selectAll("*").remove();
    chartContainer = null;
  }
}
